if paint {
  sort_deferred_groups(nodes, groups)
  let contiguous : Array[Int32] = []
  for root in groups {
    let mut parent_group : UInt64? = None
    for parent in nodes {
      if Some(parent.id) == nodes[root].parent {
        parent_group = parent.deferred_group
      }
    }
    if parent_group is None {
      contiguous.push(root)
      for child in groups {
        for parent in nodes {
          if Some(parent.id) == nodes[child].parent && parent.deferred_group == Some(nodes[root].id) {
            contiguous.push(child)
            break
          }
        }
      }
    }
  }
  groups.clear()
  for root in contiguous {
    groups.push(root)
  }
}
